    "description": "新华社惠灵顿11月7日电（记者易爱军）新西兰选举委员会7日晚公布的初步计票结果显示，在当天结束的新一届议会选举中，国家党领导的执政联盟赢得超半数席位。 在已经产生的议会130个席位中，国家党、行动党和新西兰优先党组成的执政联盟夺得67席，反对阵营的工党、绿党和毛利党赢得56席，其他党派获得剩余席位。",
    "content": "新华社惠灵顿11月7日电（记者易爱军）新西兰选举委员会7日晚公布的初步计票结果显示，在当天结束的新一届议会选举中，国家党领导的执政联盟赢得超半数席位。 在已经产生的议会130个席位中，国家党、行动党和新西兰优先党组成的执政联盟夺得67席，反对阵营的工党、绿党和毛利党赢得56席，其他党派获得剩余席位。"
