    "description": "烽烟四起的1947年，四十余名新华儿女组成中央纵队“四大队”，紧随党中央转战陕北。新华社近期携手中央戏剧学院，打造原创话剧《永远的“四大队”》。 舞台之上，再现了撤离延安、冒雨抢修天线、捷报飞越沟壑等动人瞬间。一个个鲜活的新闻战士向我们走来，他们以纸笔为刃、以电波为号，在黄土群山之间守住永不中断的党的声音。 话剧将于近日在新华社客户端、新华网上线，敬请关注。 新华社机关党委 新华社音视频部 中央戏剧学院 联合制作",
