    "description": "新华社北京11月7日电（记者白瀛、吴文诩）第七届世界媒体峰会7日在北京举行。峰会开幕式上，发布了《第七届世界媒体峰会北京共识》。 共识说，与会代表看到，人工智能正在引领新一轮科技革命和产业变革，深刻改变了人类生产生活方式和世界发展格局。愿发挥媒体独特优势，凝聚各方共识，共同推进合作行动落地见效，推动人工智能时代全球媒体转型发展。 共识说，人工智能逐渐成为媒体转型的核心动能，推动技术普惠共享是全球媒体的普遍诉求。与会代表致力于推动人工智能…",
    "content": "新华社北京11月7日电（记者白瀛、吴文诩）第七届世界媒体峰会7日在北京举行。峰会开幕式上，发布了《第七届世界媒体峰会北京共识》。 共识说，与会代表看到，人工智能正在引领新一轮科技革命和产业变革，深刻改变了人类生产生活方式和世界发展格局。愿发挥媒体独特优势，凝聚各方共识，共同推进合作行动落地见效，推动人工智能时代全球媒体转型发展。 共识说，人工智能逐渐成为媒体转型的核心动能，推动技术普惠共享是全球媒体的普遍诉求。与会代表致力于推动人工智能在媒体领域的普及和负责任应用，让技术成果惠及处于不同发展阶段的各国媒体。 共识说…"
