    "description": "中新网大连11月7日电 (记者 杨毅)11月6日，在海拔4500余米的西藏那曲市人民医院，一台历时1小时的国产手术机器人5G远程根治性左肾切除手术顺利完成。一名在那曲巴青县地震灾害中受伤的藏族群众，在地震外伤救治过程中意外查出肾脏肿瘤。依托辽宁医疗援藏力量，大连、那曲两地医疗团队紧密配合，由大连医科大学附属第二医院泌尿外科学科带头人刘志宇教授远程主刀，借助国产手术机器人与5G远程技术，顺利完成国产机器人远程肾切除术。",
