    "content": "据中央广播电视总台中国之声报道，直播间里个头饱满的黑虎虾、个头匀称的鲍鱼常常引得消费者下单，冰衣厚薄不一、头数规格缩水、进口水产溯源信息缺失等问题，在线上水产交易中多发。不少商家借着“冷冻水产特殊”的特点设置苛刻理赔门槛，直播口头宣传和商品详情标注不一致，消费者维权举证常常陷入被动。网购这类高价水产，怎样才能避开这些看不见的消费陷阱？ “告诉大家一个大好事：精心养殖的超大黑虎虾降价了！很多家人都知道，黑虎虾的价格一直居高不下。厂家刚入驻咱们平台做推广，为了快速打开知名度，直接拿出200单超大黑虎虾给大家尝鲜……”短…"
