    "description": "《醒世恒言》第三十五卷《徐老仆义愤成家》概括 开篇叙唐代杜亮侍奉性情暴躁的萧颖士，屡遭责打仍不离不弃，最终积劳而亡。正传讲明代徐哲早逝，寡妻颜氏与幼子女被大伯徐言、二伯徐召百般欺辱、刻意薄分家产。老仆阿寄心怀义愤，拿主母变卖首饰得来的十二两本钱外出经商，贩运漆米，苦心经营，逐年积累。他分文不私，赚得巨资，帮主母置田宅、教孩子读书、料理女儿婚嫁，重振家业。阿寄至死清贫，仅留旧衣，对比徐氏兄弟贪鄙，尽显忠义。",
