    "content": "“都市快报”微信公号11月7日消息，近日，有网友爆料，某剧组在云南昆明拍戏时，出现演员烧伤意外，相关路透片段在社交平台快速传播，引发大量关注。 11月7日下午，烧伤演员刘熙墨发文回应此事： 大家好，我是刘熙墨，也是这次云南剧组意外中受伤的当事人。 首先想借这个机会，向所有关心我的粉丝、网友和各界朋友说一声谢谢，也正式给大家报个平安。 当天晚上拍摄的是剧中与非遗喷火相关的外景。剧组其实已经做好了完备的安全预案——灭火器等防护设备全部到位，特技替身也随时待命。因为我之前学习过非遗喷火，也多次公开表演过，所以主动跟剧组提…"
