    "description": "这几天 DSH 的生成插件能力广受人民群众好评，我想到了在 DSH 里刷微博这个需求。之前有个 app 叫 VVebo ，刷微博很好用，但现在已经下架了很久了，在电脑上打开这个 app 有时也有一些 bug ，总之体验肯定是一直下降的。 能让 DSH 用类似 Rea 的功能参考已经在电脑上安装的 VVebo 造一个刷微博的插件吗？这难度是不是很大？",
