    "content": "新华社德黑兰11月7日电（记者刁慧琳 沙达提）据伊朗伊斯兰共和国广播电视台7日报道，伊朗海军公共关系部门当天发表声明说，一艘油轮在霍尔木兹海峡东部触雷起火并停止航行。 声明说，这艘油轮当天上午“一再无视警告”，在禁航且不安全海域航行，并关闭了导航系统。声明强调，“所有无视警告、在禁航区域航行的违规船只和舰艇，下场都会如此”。"
