    "description": "新华社兰州11月7日电（记者张玉洁、郎兵兵）7日，“丹霞千龛 多彩华章——炳灵寺石窟展”在甘肃省兰州市开幕。本次展览是甘肃炳灵寺文物保护研究所自1955年成立以来，文物首次走出石窟、面向社会举办的展览。 炳灵寺石窟是首批全国重点文物保护单位，也是世界文化遗产“丝绸之路：长安—天山廊道的路网”的遗产点之一。第169窟留存的建弘元年题记，是国内现存最早有明确纪年的题记，为我国早期石窟考古断代提供了重要标尺。 甘肃炳灵寺文物保护研究所所长张铭…",
    "content": "新华社兰州11月7日电（记者张玉洁、郎兵兵）7日，“丹霞千龛 多彩华章——炳灵寺石窟展”在甘肃省兰州市开幕。本次展览是甘肃炳灵寺文物保护研究所自1955年成立以来，文物首次走出石窟、面向社会举办的展览。 炳灵寺石窟是首批全国重点文物保护单位，也是世界文化遗产“丝绸之路：长安—天山廊道的路网”的遗产点之一。第169窟留存的建弘元年题记，是国内现存最早有明确纪年的题记，为我国早期石窟考古断代提供了重要标尺。 甘肃炳灵寺文物保护研究所所长张铭介绍，本次展览的展品均为炳灵寺文保所馆藏，共165件（套），其中文物152件、复…"
