    "description": "新华社郑州11月7日电（记者王烁）今日，我们迎来了立冬节气。民间素有“立冬补冬”的说法，不少人提前备好牛羊肉打算好好补一补。对此，河南中医药大学第一附属医院针灸科副主任医师郭昭昭提醒，立冬养生的第一件事不是“补”，而是“藏”。 “所谓‘藏’，指的是顺应季节节律，减少不必要的消耗。”郭昭昭说，《黄帝内经》中写道：“冬三月，此谓闭藏，水冰地坼，无扰乎阳。”其大意是天寒地冻，人体应减少消耗、注重休整。冬季昼短夜长，作息、运动、饮食都应相应调整…",
    "content": "新华社郑州11月7日电（记者王烁）今日，我们迎来了立冬节气。民间素有“立冬补冬”的说法，不少人提前备好牛羊肉打算好好补一补。对此，河南中医药大学第一附属医院针灸科副主任医师郭昭昭提醒，立冬养生的第一件事不是“补”，而是“藏”。 “所谓‘藏’，指的是顺应季节节律，减少不必要的消耗。”郭昭昭说，《黄帝内经》中写道：“冬三月，此谓闭藏，水冰地坼，无扰乎阳。”其大意是天寒地冻，人体应减少消耗、注重休整。冬季昼短夜长，作息、运动、饮食都应相应调整，留足休息时间，为来年开春打好基础。 图片由AI辅助生成。 起居方面，传统讲究“…"
