    "description": "新华社香港11月7日电（奚天麒）由香港特区政府民政及青年事务局主办的第三届香港·青年发展高峰论坛7日在香港会议展览中心举行。 此次论坛以“开拓青年新领域 逐梦前行创未来”为主题，吸引超过3300名青年登记参加，他们来自香港、内地以及海外35个国家和地区。来自不同地区推动青年发展的主要官员及不同领域业界翘楚担任演讲嘉宾，就青年关心的议题交流学习。 香港特区行政长官李家超通过视频致辞表示，特区政府会积极落实香港首个五年规划中有关青年发展的工…",
    "content": "新华社香港11月7日电（奚天麒）由香港特区政府民政及青年事务局主办的第三届香港·青年发展高峰论坛7日在香港会议展览中心举行。 此次论坛以“开拓青年新领域 逐梦前行创未来”为主题，吸引超过3300名青年登记参加，他们来自香港、内地以及海外35个国家和地区。来自不同地区推动青年发展的主要官员及不同领域业界翘楚担任演讲嘉宾，就青年关心的议题交流学习。 香港特区行政长官李家超通过视频致辞表示，特区政府会积极落实香港首个五年规划中有关青年发展的工作，为青年创造更多元的发展机遇，培养青年成为爱国爱港、具备世界视野、有抱负和具正…"
