    "description": "中新网11月7日电 据中央气象台网站消息，中央气象台11月7日18时继续发布暴雪黄色预警：预计11月7日20时至8日20时，北京西部和北部、天津北部、河北北部、辽宁西部和南部、内蒙古东南部、山西东北部以及甘肃中西部、青海东北部等地部分地区有大到暴雪，其中，辽宁西部、河北东北部等地部分地区有大暴雪，局地特大暴雪(30～32毫米)。上述部分地区新增积雪深度5～15厘米，局地可达20厘米以上。",
