    "pub_date": "2026-11-07 17:21:12",
    "author": "",
    "description": "新华社德黑兰11月7日电（记者刁慧琳 沙达提）伊朗外长阿拉格齐7日在社交媒体上说，过去48小时分别与12国外长通电话讨论地区和国际局势。 阿拉格齐说，他分别与阿曼、埃及、约旦、沙特阿拉伯、卡塔尔、塞浦路斯、土耳其、科威特、阿联酋、突尼斯、伊拉克和巴基斯坦12国外长通电话。在这些通话中，他阐述了伊朗的原则立场，强调必须尊重各国国家主权，停止侵略和威胁，避免外部势力进行破坏性干涉。他同时强调，地区国家有责任防止不安全局势进一步升级。 他表示…",
