    "description": "新华社昆明11月7日电（记者严勇）在中国西南的云南山林深处，一种被誉为“凤凰”原型的古老生灵正在上演一场令人惊叹的“回归”故事。 绿孔雀，中国唯一的本土原生孔雀物种，也是古代神话中“凤凰”的主要原型。它身披金翠交错的羽毛，冠羽呈标志性的簇状，在汉唐时期就出现在诗词歌赋与官服纹饰之中，是中华文化中吉祥与高贵的象征。然而，这种美丽生灵的处境曾一度令人担忧——2015年前后，中国境内的野生绿孔雀不足500只，被世界自然保护联盟列为濒危。 20…",
    "content": "新华社昆明11月7日电（记者严勇）在中国西南的云南山林深处，一种被誉为“凤凰”原型的古老生灵正在上演一场令人惊叹的“回归”故事。 绿孔雀，中国唯一的本土原生孔雀物种，也是古代神话中“凤凰”的主要原型。它身披金翠交错的羽毛，冠羽呈标志性的簇状，在汉唐时期就出现在诗词歌赋与官服纹饰之中，是中华文化中吉祥与高贵的象征。然而，这种美丽生灵的处境曾一度令人担忧——2015年前后，中国境内的野生绿孔雀不足500只，被世界自然保护联盟列为濒危。 2025年5月19日在云南森林自然中心拍摄的绿孔雀。新华社记者 胡超 摄 如今，这一…"
