    "content": "新华社里约热内卢11月6日电（记者赵焱）亚松森消息：巴拉圭国会6日通过对总统圣地亚哥·培尼亚的弹劾议案，认定其存在渎职等行为，解除其总统职务。当晚，培尼亚在位于首都亚松森的私人住所被警方逮捕。同日，副总统佩德罗·阿利亚纳宣誓就任总统。以下是巴拉圭此次政治危机的要点解读： ——起因：银行被查封 这场政治危机的起因是巴拉圭最大的数字银行韦诺银行被查封，数百万客户无法提取存款，而培尼亚本人曾是韦诺银行控股股东。 这是11月2日培尼亚在巴拉圭首都亚松森出席活动的资料照片。（新华社发） 韦诺银行前身是一家金融公司，2023年…"
