    "description": "历经17年磋商，韩国产甜柿将首次输华。 综合韩联社和韩国《每日经济》报道，韩国农林畜产食品部（农食品部）和韩国农水产食品流通公社（aT）星期五（11月6日）介绍，韩国甜柿对华出口首批货物装船仪式当天在庆尚南道昌原市举行。 昌原是占韩国甜柿99%出口量的最大主产地。这次出口的甜柿总重约19.6吨，共1960箱。这批从东邑农协和庆南甜柿园艺农协筛选包装的甜柿，将从釜山港出发，预计于下星期二（11月10日）抵达上海，之后将在高级流通卖场等地门…",
    "content": "历经17年磋商，韩国产甜柿将首次输华。 综合韩联社和韩国《每日经济》报道，韩国农林畜产食品部（农食品部）和韩国农水产食品流通公社（aT）星期五（11月6日）介绍，韩国甜柿对华出口首批货物装船仪式当天在庆尚南道昌原市举行。 昌原是占韩国甜柿99%出口量的最大主产地。这次出口的甜柿总重约19.6吨，共1960箱。这批从东邑农协和庆南甜柿园艺农协筛选包装的甜柿，将从釜山港出发，预计于下星期二（11月10日）抵达上海，之后将在高级流通卖场等地门店销售。 韩中两国在2008年启动‌韩国甜柿输华检疫谈判，持续了17年，直至以去…"
