    "content": "新华社达喀尔11月6日电 题：一路颠沛 一路相伴——难民代表队首登青奥会 新华社记者胡佳丽、高剑飞、洪泽华 15岁的阿诺·亚丰加站上柔道垫，场边目光始终追随着他的，是他的教练，也是他的父亲阿诺德·亚丰加。 从肯尼亚卡库马难民营到达喀尔青奥会，父子俩一路颠沛、一路相伴。这一次，阿诺成为首位在青奥会赛场上亮相的难民代表队运动员，并一路闯入男子55公斤级铜牌战，最终获得第五名。 “这是奥林匹克赛事首次来到非洲，规模如此盛大。看到阿诺在这里参赛，我感到无比高兴，梦想成真了。”阿诺德说，“他已经尽力了，在柔道中，跌倒了就要重…"
