    "content": "快科技11月7日消息，近日，特斯拉CEO埃隆·马斯克在纽约出席第33届巴伦投资会议，在接受巴伦资本创始人罗恩·巴伦采访时，公开表达对中国的喜爱，并高度评价中国汽车公司的竞争力。 马斯克在采访中表示：“中国令人惊叹。顺便说一句，我爱中国。去那里的旅行令人深受鼓舞。” 他同时强调，在上海生产的特斯拉Model Y是中国最畅销的电动汽车，但取得这一成绩并不容易，“想一想就知道了，中国汽车公司非常厉害。” 这并非马斯克首次公开赞美中国。此前他多次在社交平台发文盛赞中国：“中国太棒了。我强烈鼓励大家去那里旅游。” 随后，他的…"
