    "content": "新华社南宁11月7日电（记者曹祎铭、孙闯）轻风拂碧波，舟行越江海。作为西部陆海新通道骨干工程，平陆运河自今年9月16日正式通航以来，在发挥综合经济效益的同时，文旅带动作用也逐渐显现。从乘船观光到岸边拍照打卡，游客和市民正用不同的方式走近运河、感受运河，沿线文旅融合新图景正随着运河上驶过的船只愈加精彩。 “震撼！置身在运河之上，我为祖国的发展感到自豪。”11月4日，77岁的北京游客孙桂萍与老伴一起从位于广西横州市的平陆运河新福水上综合服务区登上游船，开启了历时2个小时的平陆运河水上观光游。孙桂萍告诉记者，她与共和国同…"
