    "title": "全国约2300万孩子长期受它折磨，却只有3%就医治疗！",
    "link": "https://www.guokr.com/article/470651/",
    "pub_date": "2026-11-07 16:15:04",
    "author": "",
    "description": "近年来，带孩子来医院看注意力问题的家庭越来越多，特别每逢周末、假期，就诊人数会出现小高峰，已经成了一个无须预测的规律。 前来就诊的家长往往是因为“老师让把孩子带过来看看”，问其自己对孩子情况有何感受，家长们翻牌率最高的问题就是——“多动症不治疗，自己会好吗？” 多动症不治疗，会不会自己好呢？ 有这样的想法，其实情有可原，因为平时偶尔会有一些类似“某个人小时候调皮得像个多动症，家长没管它，长大了考上大学”这类信息见诸报端，所以，家长内心对…",
