    "author": "",
    "description": "在两国关系持续回暖的背景下，中国将首次在加拿大发行人民币主权债券。 中国财政部星期四（11月5日）在官网公告，经中国国务院批准，财政部将于今年11月9日当周在加拿大发行人民币绿色主权债券，规模不超过40亿元人民币（7.69亿新元）。具体发行安排将在发行前另行公布。 据彭博社报道，中国财政部2009年开始在香港发行人民币国债，2016年首次将发行拓展至香港以外的离岸市场，在伦敦发行30亿元人民币国债。待这次发行落地，加拿大将成为继香港、伦…",
    "content": "在两国关系持续回暖的背景下，中国将首次在加拿大发行人民币主权债券。 中国财政部星期四（11月5日）在官网公告，经中国国务院批准，财政部将于今年11月9日当周在加拿大发行人民币绿色主权债券，规模不超过40亿元人民币（7.69亿新元）。具体发行安排将在发行前另行公布。 据彭博社报道，中国财政部2009年开始在香港发行人民币国债，2016年首次将发行拓展至香港以外的离岸市场，在伦敦发行30亿元人民币国债。待这次发行落地，加拿大将成为继香港、伦敦和澳门之后，中国人民币主权债券发行的又一个境外市场，有助于扩大人民币资产在北美…"
