    "content": "新华社纽约11月6日电（记者刘亚南）鉴于美国选民对高生活成本和高通胀反应强烈，随着民主党在中期选举中取得压倒性胜利，多名民主党籍国会议员表示将致力于推动撤销现行的不合理关税政策。 来自马萨诸塞州的民主党籍联邦众议员理查德·尼尔6日说，自己致力于扭转特朗普政府的不合理关税和幕后贸易协议。 尼尔有望在明年年初担任新一届国会众议院筹款委员会主席。当天，他在出席公开活动时说，特朗普政府有意制造混乱，推行不合理的贸易政策，导致生活成本上涨，让美国的贫富不均现象加剧。 来自俄勒冈州的民主党籍联邦参议员罗恩·怀登说，在明年1月担…"
